// XdgToplevel is a client side proxy for xdg_toplevel. This interface defines an xdg_surface role which allows a surface to, among other things, set window-like prop...
pub struct XdgToplevel {
	wayland.Object
}

// xdg_toplevel_proxy wraps an object id in a XdgToplevel proxy.
pub fn xdg_toplevel_proxy(conn &wayland.Connection, id u32) XdgToplevel {
	return XdgToplevel{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'xdg_toplevel'
		}
	}
}

// XdgToplevelListener receives the events of a xdg_toplevel object.
pub interface XdgToplevelListener {
	// This configure event asks the client to resize its toplevel surface or to change its state.
mut:
	configure(proxy XdgToplevel, width i32, height i32, states []u8)
	// The close event is sent by the compositor when the user wants the surface to be closed.
	close(proxy XdgToplevel)
	// The configure_bounds event may be sent prior to a xdg_toplevel.
	configure_bounds(proxy XdgToplevel, width i32, height i32)
	// This event advertises the capabilities supported by the compositor.
	wm_capabilities(proxy XdgToplevel, capabilities []u8)
}

// NoopXdgToplevelListener ignores every xdg_toplevel event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopXdgToplevelListener {}

pub fn (mut listener NoopXdgToplevelListener) configure(_proxy XdgToplevel, _width i32, _height i32, _states []u8) {
}

pub fn (mut listener NoopXdgToplevelListener) close(_proxy XdgToplevel) {
}

pub fn (mut listener NoopXdgToplevelListener) configure_bounds(_proxy XdgToplevel, _width i32, _height i32) {
}

pub fn (mut listener NoopXdgToplevelListener) wm_capabilities(_proxy XdgToplevel, _capabilities []u8) {
}

struct XdgToplevelSink {
mut:
	proxy    XdgToplevel
	listener XdgToplevelListener = NoopXdgToplevelListener{}
}

fn (mut s XdgToplevelSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			width := msg.arg_i32(0)!
			height := msg.arg_i32(1)!
			states := msg.arg_array(2)!
			s.listener.configure(s.proxy, width, height, states)
		}
		1 {
			s.listener.close(s.proxy)
		}
		2 {
			width := msg.arg_i32(0)!
			height := msg.arg_i32(1)!
			s.listener.configure_bounds(s.proxy, width, height)
		}
		3 {
			capabilities := msg.arg_array(0)!
			s.listener.wm_capabilities(s.proxy, capabilities)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives xdg_toplevel events.
pub fn (proxy &XdgToplevel) set_listener(listener XdgToplevelListener) ! {
	proxy.conn.set_sink(proxy.id, XdgToplevelSink{
		proxy:    *proxy
		listener: listener
	})!
}

// This request destroys the role surface and unmaps the surface; see "Unmapping" behavior in interface section f...
pub fn (proxy &XdgToplevel) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// Set the "parent" of this surface.
pub fn (proxy &XdgToplevel) set_parent(parent ?XdgToplevel) ! {
	parent_id := if value := parent { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(wayland.ObjectRef{ id: parent_id })])!
}

// Set a short title for the surface.
pub fn (proxy &XdgToplevel) set_title(title string) ! {
	proxy.conn.request(proxy.id, 2, [wayland.ArgValue(title)])!
}

// Set an application identifier for the surface.
pub fn (proxy &XdgToplevel) set_app_id(app_id string) ! {
	proxy.conn.request(proxy.id, 3, [wayland.ArgValue(app_id)])!
}

// Clients implementing client-side decorations might want to show a context menu when right-clicking on the deco...
pub fn (proxy &XdgToplevel) show_window_menu(seat wayland.WlSeat, serial u32, x i32, y i32) ! {
	proxy.conn.request(proxy.id, 4, [
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id }),
		wayland.ArgValue(serial),
		wayland.ArgValue(x),
		wayland.ArgValue(y),
	])!
}

// Start an interactive, user-driven move of the surface.
pub fn (proxy &XdgToplevel) move(seat wayland.WlSeat, serial u32) ! {
	proxy.conn.request(proxy.id, 5, [
