		wayland.ArgValue(serial),
	])!
}

// Start a user-driven, interactive resize of the surface.
pub fn (proxy &XdgToplevel) resize(seat wayland.WlSeat, serial u32, edges u32) ! {
	proxy.conn.request(proxy.id, 6, [
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id }),
		wayland.ArgValue(serial),
		wayland.ArgValue(edges),
	])!
}

// Set a maximum size for the window.
pub fn (proxy &XdgToplevel) set_max_size(width i32, height i32) ! {
	proxy.conn.request(proxy.id, 7, [wayland.ArgValue(width), wayland.ArgValue(height)])!
}

// Set a minimum size for the window.
pub fn (proxy &XdgToplevel) set_min_size(width i32, height i32) ! {
	proxy.conn.request(proxy.id, 8, [wayland.ArgValue(width), wayland.ArgValue(height)])!
}

// Maximize the surface. After requesting that the surface should be maximized, the compositor will respond by em...
pub fn (proxy &XdgToplevel) set_maximized() ! {
	proxy.conn.request(proxy.id, 9, []wayland.ArgValue{})!
}

// Unmaximize the surface. After requesting that the surface should be unmaximized, the compositor will respond b...
pub fn (proxy &XdgToplevel) unset_maximized() ! {
	proxy.conn.request(proxy.id, 10, []wayland.ArgValue{})!
}

// Make the surface fullscreen.
pub fn (proxy &XdgToplevel) set_fullscreen(output ?wayland.WlOutput) ! {
	output_id := if value := output { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 11, [wayland.ArgValue(wayland.ObjectRef{ id: output_id })])!
}

// Make the surface no longer fullscreen.
pub fn (proxy &XdgToplevel) unset_fullscreen() ! {
	proxy.conn.request(proxy.id, 12, []wayland.ArgValue{})!
}

// Request that the compositor minimize your surface.
pub fn (proxy &XdgToplevel) set_minimized() ! {
	proxy.conn.request(proxy.id, 13, []wayland.ArgValue{})!
}

